<tool_parameter>contents">import express from "express";
import bcrypt from "bcrypt";
import jwt from "jsonwebtoken";
import rateLimit from "express-rate-limit";
import Database from "better-sqlite3";
import dotenv from "dotenv";

dotenv.config();

const app = express();
const db = new Database(":memory:");
const JWT_SECRET = process.env.JWT_SECRET || "your-secret-key-change-in-production";
const JWT_EXPIRY = "24h";

app.use(express.json());

// Initialize database
db.exec(`
  CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    email TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );

  CREATE TABLE IF NOT EXISTS failed_attempts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    email TEXT NOT NULL,
    attempted_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (email) REFERENCES users(email)
  );
`);

// Rate limiter: 5 failed attempts per email in 15 minutes
const checkRateLimit = (req, res, next) => {
  const email = req.body.email?.toLowerCase();
  if (!email) return res.status(400).json({ error: "Email required" });

  const fifteenMinutesAgo = new Date(Date.now() - 15 * 60 * 1000);
  const attempts = db
    .prepare(
      "SELECT COUNT(*) as count FROM failed_attempts WHERE email = ? AND attempted_at > ?"
    )
    .get(email, fifteenMinutesAgo.toISOString());

  if (attempts.count >= 5) {
    return res.status(429).json({
      error: "Too many failed login attempts. Try again in 15 minutes.",
    });
  }

  next();
};

const recordFailedAttempt = (email) => {
  db.prepare("INSERT INTO failed_attempts (email) VALUES (?)").run(email);
};

const clearFailedAttempts = (email) => {
  db.prepare("DELETE FROM failed_attempts WHERE email = ?").run(email);
};

// Signup endpoint
app.post("/signup", async (req, res) => {
  try {
    const { email, password } = req.body;

    if (!email || !password) {
      return res
        .status(400)
        .json({ error: "Email and password required" });
    }

    if (password.length < 8) {
      return res
        .status(400)
        .json({ error: "Password must be at least 8 characters" });
    }

    const existingUser = db
      .prepare("SELECT id FROM users WHERE email = ?")
      .get(email.toLowerCase());

    if (existingUser) {
      return res.status(409).json({ error: "Email already registered" });
    }

    const passwordHash = await bcrypt.hash(password, 12);
    const result = db
      .prepare("INSERT INTO users (email, password_hash) VALUES (?, ?)")
      .run(email.toLowerCase(), passwordHash);

    const token = jwt.sign(
      { userId: result.lastID, email: email.toLowerCase() },
      JWT_SECRET,
      { expiresIn: JWT_EXPIRY }
    );

    res.status(201).json({
      message: "User created successfully",
      token,
      user: { id: result.lastID, email: email.toLowerCase() },
    });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Login endpoint
app.post("/login", [checkRateLimit], async (req, res) => {
  try {
    const { email, password } = req.body;
    const emailLower = email.toLowerCase();

    const user = db
      .prepare("SELECT id, email, password_hash FROM users WHERE email = ?")
      .get(emailLower);

    if (!user) {
      recordFailedAttempt(emailLower);
      return res.status(401).json({ error: "Invalid email or password" });
    }

    const passwordMatch = await bcrypt.compare(password, user.password_hash);

    if (!passwordMatch) {
      recordFailedAttempt(emailLower);
      return res.status(401).json({ error: "Invalid email or password" });
    }

    clearFailedAttempts(emailLower);

    const token = jwt.sign(
      { userId: user.id, email: user.email },
      JWT_SECRET,
      { expiresIn: JWT_EXPIRY }
    );

    res.json({
      message: "Login successful",
      token,
      user: { id: user.id, email: user.email },
    });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Verify token middleware
const verifyToken = (req, res, next) => {
  const authHeader = req.headers.authorization;
  const token = authHeader?.split(" ")[1];

  if (!token) {
    return res.status(401).json({ error: "No token provided" });
  }

  try {
    const decoded = jwt.verify(token, JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    res.status(401).json({ error: "Invalid or expired token" });
  }
};

// Protected route example
app.get("/profile", verifyToken, (req, res) => {
  res.json({
    message: "Access granted",
    user: req.user,
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Auth server running on http://localhost:${PORT}`);
});
